import { useEffect, useMemo, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'

type Screen = 'public' | 'request' | 'admin' | 'members' | 'memberships' | 'payments' | 'attendance' | 'leads' | 'reports' | 'member-portal' | 'member-attendance' | 'member-payments' | 'member-membership'
type Modal = 'add-member' | 'follow-up' | 'payment' | 'attendance' | 'renew' | 'request' | null
type MemberStatus = 'فعال' | 'رو به پایان' | 'منقضی' | 'بدهکار' | 'غیرفعال'
type RiskLevel = 'پایدار' | 'نیازمند توجه' | 'در معرض ریزش'

type Member = { id: number; name: string; phone: string; status: MemberStatus; plan: string; expiry: string; lastVisit: string; visits: number; locker: string; joined: string; avatar: string; risk: RiskLevel; riskReason: string }
type Membership = { id: number; memberId: number; plan: string; start: string; end: string; price: number; status: MemberStatus }
type Payment = { id: number; memberId: number; amount: number; date: string; type: string; method: string; status: 'پرداخت موفق' | 'بدهکار' }
type Attendance = { id: number; memberId: number; date: string; time: string; method: 'QR' | 'پذیرش' }
type TimelineItem = { id: number; memberId: number; date: string; title: string; detail?: string; tone: 'lime' | 'orange' | 'blue' }
type Lead = { id: number; name: string; phone: string; plan: string; created: string; status: 'جدید' | 'در حال پیگیری' | 'تبدیل شده' }
type Toast = { id: number; message: string; type?: 'success' | 'neutral' }

const screenFromPath = (): Screen => ({
  '/': 'public', '/membership': 'request', '/admin': 'admin', '/admin/members': 'members', '/admin/memberships': 'memberships',
  '/admin/payments': 'payments', '/admin/attendance': 'attendance', '/admin/leads': 'leads', '/admin/reports': 'reports',
  '/member': 'member-portal', '/member/attendance': 'member-attendance', '/member/payments': 'member-payments', '/member/membership': 'member-membership',
} as Record<string, Screen>)[window.location.pathname] || 'public'

const pathForScreen = (screen: Screen) => ({
  public: '/', request: '/membership', admin: '/admin', members: '/admin/members', memberships: '/admin/memberships', payments: '/admin/payments',
  attendance: '/admin/attendance', leads: '/admin/leads', reports: '/admin/reports', 'member-portal': '/member', 'member-attendance': '/member/attendance',
  'member-payments': '/member/payments', 'member-membership': '/member/membership',
} as Record<Screen, string>)[screen]

const names = ['محمد رضایی', 'علی کریمی', 'رضا احمدی', 'امیر مرادی', 'سینا حسینی', 'حامد نادری', 'مهدی اکبری', 'پارسا نوروزی', 'یاسر حبیبی', 'فرهاد جلیلی', 'کاوه رستمی', 'وحید شریفی', 'نوید صادقی', 'اشکان رجبی', 'میلاد توکلی', 'پویان صمیمی', 'آرش محمدی', 'سامان نوری', 'مازیار کاظمی', 'بهرام شریفی', 'کیانوش مرادی', 'نیما یوسفی', 'شایان کریمی', 'رامین فلاح', 'پوریا نادری', 'عرفان مهدوی', 'سروش اکبری', 'مانی رحیمی', 'آریا حسینی', 'بهنام قاسمی', 'احسان رضوانی', 'سهیل رستگار', 'مهران توکلی', 'ابراهیم صادقی', 'نوذر رفیعی', 'علیرضا صالحی', 'دانیال مرادی', 'مسیح نوروزی', 'سام راد', 'فرزاد حیدری', 'کمال رضایی', 'حمیدرضا کریمی', 'مهدی رستمی', 'شهاب نیکنام', 'رامتین احمدی', 'حسن عباسی', 'مهرشاد یزدانی', 'مجتبی فلاح', 'یونس مرادی', 'کامران شفیعی']
const statusFor = (index: number): MemberStatus => index < 28 ? 'فعال' : index < 34 ? 'رو به پایان' : index < 40 ? 'منقضی' : index < 45 ? 'بدهکار' : 'غیرفعال'
const planFor = (index: number) => ['سه‌ماهه', 'شش‌ماهه', 'یک‌ماهه'][index % 3]
const initials = (name: string) => name.split(' ').map(part => part[0]).join('').slice(0, 2)
const toLatinDigits = (value: string) => value.replace(/[۰-۹]/g, digit => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit)))
const makeMember = (index: number): Member => {
  const status = statusFor(index)
  const risk: RiskLevel = status === 'غیرفعال' || status === 'منقضی' ? 'در معرض ریزش' : status === 'رو به پایان' || status === 'بدهکار' ? 'نیازمند توجه' : 'پایدار'
  const reason = status === 'غیرفعال' ? `${7 + index % 18} روز بدون مراجعه` : status === 'منقضی' ? 'عضویت منقضی شده و نیاز به بازگشت دارد' : status === 'رو به پایان' ? 'کمتر از ۷ روز تا پایان عضویت' : status === 'بدهکار' ? 'یک پرداخت در انتظار پیگیری' : 'حضور منظم و روند پایدار'
  return { id: index + 1, name: names[index], phone: `09${12 + index % 8} ${String(120 + index * 17).slice(0, 3)} ${String(1900 + index * 73).slice(0, 4)}`, status, plan: planFor(index), expiry: index === 0 ? '۲۴ شهریور ۱۴۰۵' : status === 'منقضی' ? '۲۸ مرداد ۱۴۰۵' : status === 'رو به پایان' ? `${12 + index % 10} شهریور ۱۴۰۵` : `${20 + index % 9} آبان ۱۴۰۵`, lastVisit: status === 'غیرفعال' ? `${8 + index % 17} روز پیش` : status === 'منقضی' ? `${6 + index % 8} روز پیش` : index % 4 === 0 ? 'امروز، ۱۸:۴۲' : `${1 + index % 5} روز پیش`, visits: status === 'غیرفعال' ? 2 + index % 5 : 8 + index % 22, locker: `${['A', 'B', 'C'][index % 3]}-${String(1 + index).padStart(2, '0')}`, joined: `${10 + index % 18} خرداد ۱۴۰۵`, avatar: initials(names[index]), risk, riskReason: reason }
}
const initialMembers = names.map((_, index) => makeMember(index))
const initialMemberships: Membership[] = initialMembers.map(member => ({ id: member.id, memberId: member.id, plan: member.plan, start: member.joined, end: member.expiry, price: member.plan === 'یک‌ماهه' ? 2800000 : member.plan === 'سه‌ماهه' ? 7500000 : 13500000, status: member.status }))
const initialPayments: Payment[] = initialMembers.slice(0, 28).map((member, index) => ({ id: index + 1, memberId: member.id, amount: member.plan === 'شش‌ماهه' ? 13500000 : member.plan === 'سه‌ماهه' ? 7500000 : 2800000, date: index < 3 ? 'امروز، ۱۸:۴۰' : `${index + 1} شهریور ۱۴۰۵`, type: index % 4 === 0 ? 'تمدید عضویت' : 'عضویت جدید', method: index % 2 ? 'کارتخوان' : 'درگاه آنلاین', status: 'پرداخت موفق' }))
const initialAttendance: Attendance[] = Array.from({ length: 92 }, (_, index) => { const member = initialMembers[index % 18]; return { id: index + 1, memberId: member.id, date: index < 12 ? 'امروز، ۵ شهریور' : `${1 + index % 4} شهریور ۱۴۰۵`, time: ['۱۸:۴۲', '۱۸:۳۷', '۱۷:۵۵', '۱۶:۰۵', '۱۴:۲۲', '۱۳:۲۵'][index % 6], method: index % 3 ? 'QR' : 'پذیرش' } })
const initialLeads: Lead[] = [
  { id: 101, name: 'نوید صادقی', phone: '0912 931 7014', plan: 'سه‌ماهه', created: 'امروز، ۰۹:۲۴', status: 'جدید' },
  { id: 102, name: 'اشکان رجبی', phone: '0935 404 8421', plan: 'شش‌ماهه', created: 'دیروز، ۱۸:۱۰', status: 'در حال پیگیری' },
  { id: 103, name: 'میلاد توکلی', phone: '0910 866 3440', plan: 'یک‌ماهه', created: '۲ روز پیش', status: 'جدید' },
  { id: 104, name: 'پویان صمیمی', phone: '0991 207 4950', plan: 'سه‌ماهه', created: '۳ روز پیش', status: 'تبدیل شده' },
]
const navGroups = [
  { label: 'نمای کلی', items: [{ id: 'admin', label: 'داشبورد', icon: '⌂' }] },
  { label: 'عملیات باشگاه', items: [{ id: 'members', label: 'اعضا', icon: '◎' }, { id: 'memberships', label: 'عضویت‌ها', icon: '◫' }, { id: 'payments', label: 'پرداخت‌ها', icon: '↙' }, { id: 'attendance', label: 'حضور و غیاب', icon: '⌁' }] },
  { label: 'رشد', items: [{ id: 'leads', label: 'درخواست‌ها', icon: '✦' }, { id: 'reports', label: 'گزارش‌ها', icon: '◒' }] },
]

function Icon({ children }: { children: ReactNode }) { return <span className="icon" aria-hidden="true">{children}</span> }
function StatusBadge({ status }: { status: string }) { return <span className={`badge badge-${status.replaceAll(' ', '-')}`}>{status}</span> }
function Avatar({ member, size = 'md' }: { member: Member; size?: 'sm' | 'md' | 'lg' }) { return <div className={`avatar avatar-${size}`}>{member.avatar}</div> }
function Button({ children, variant = 'primary', onClick, type = 'button', full = false }: { children: ReactNode; variant?: 'primary' | 'ghost' | 'dark' | 'danger'; onClick?: () => void; type?: 'button' | 'submit'; full?: boolean }) { return <button type={type} onClick={onClick} className={`button button-${variant}${full ? ' button-full' : ''}`}>{children}</button> }
function PageHeader({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action && <div className="header-action">{action}</div>}</div> }
function EmptyState({ title = 'موردی پیدا نشد', description = 'با تغییر فیلتر یا جستجو دوباره امتحان کنید.' }: { title?: string; description?: string }) { return <div className="empty-state"><div className="empty-icon">⌁</div><h3>{title}</h3><p>{description}</p></div> }

function PublicNav({ onNavigate, onDemo, onRequest }: { onNavigate: (screen: Screen) => void; onDemo: () => void; onRequest: () => void }) { return <header className="public-nav"><div className="brand-lockup"><div className="brand-mark">FL</div><div><strong>Fit Land Gym</strong><span>باشگاه بدنسازی آقایان</span></div></div><nav><button onClick={() => onNavigate('public')}>خانه</button><button onClick={() => document.getElementById('facilities')?.scrollIntoView({ behavior: 'smooth' })}>امکانات</button><button onClick={() => document.getElementById('membership')?.scrollIntoView({ behavior: 'smooth' })}>تعرفه‌ها</button><button onClick={() => document.getElementById('faq')?.scrollIntoView({ behavior: 'smooth' })}>سوالات متداول</button><button onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}>تماس</button></nav><div className="nav-actions"><button className="text-button" onClick={onDemo}>ورود به Demo</button><Button onClick={onRequest}>شروع عضویت <span>←</span></Button></div></header> }
function PublicPage({ onNavigate, onRequest }: { onNavigate: (screen: Screen) => void; onRequest: () => void }) {
  const [activeFaq, setActiveFaq] = useState(0); const faqs = ['آیا برای شروع نیاز به تجربه قبلی دارم؟', 'ساعات کاری باشگاه چگونه است؟', 'آیا امکان بازدید قبل از عضویت وجود دارد؟']
  return <div className="public-page"><PublicNav onNavigate={onNavigate} onDemo={() => onNavigate('admin')} onRequest={onRequest}/><main>
    <section className="public-hero"><div className="hero-glow"/><div className="hero-copy"><div className="eyebrow eyebrow-light"><span className="eyebrow-dot"/> باشگاه بدنسازی حرفه‌ای آقایان · مدیریت رضا دشتی</div><h1>اینجا، نسخه<br/><em>قوی‌تر تو</em> شروع می‌شود.</h1><p>تجهیزات کامل، محیط مدرن و فضای تمرینی استاندارد؛ برای کسانی که تصمیم گرفته‌اند جدی‌تر از همیشه تمرین کنند.</p><div className="hero-actions"><Button onClick={onRequest}>شروع عضویت <span>←</span></Button><button className="outline-button" onClick={() => document.getElementById('facilities')?.scrollIntoView({ behavior: 'smooth' })}>مشاهده امکانات <span>↙</span></button></div><div className="hero-note"><span className="mini-avatars"><i>م</i><i>ع</i><i>ر</i><i>+</i></span><span>جامعه‌ای از آقایان جدی و باانگیزه</span></div></div><div className="hero-visual"><div className="hero-image"/><div className="hero-float hero-float-top"><span className="live-dot"/> امروز باشگاه زنده است<div className="float-number">۳۸ <small>عضو فعال</small></div></div><div className="hero-float hero-float-bottom"><span>ساعت کاری</span><strong>۰۶—۲۳:۳۰</strong><small>هر روز · آقایان</small></div></div></section>
    <section className="metric-strip"><div><strong>۱۲۰۰<span>m²</span></strong><span>فضای تمرین حرفه‌ای</span></div><div><strong>۰۶<span>—۲۳:۳۰</span></strong><span>هر روز در کنار شما</span></div><div><strong>۴.۹<span>/۵</span></strong><span>رضایت اعضا</span></div><div className="metric-quote">«قوی بودن، یک تصمیم روزانه است.»</div></section>
    <section id="facilities" className="public-section facilities-section"><div className="section-intro"><div><div className="eyebrow">فضایی برای جدی‌تر شدن</div><h2>هر چیزی که برای<br/><em>پیشرفت</em> لازم داری.</h2></div><p>در Fit Land Gym، طراحی فضا و انتخاب تجهیزات با یک هدف انجام شده: تجربه تمرینی بی‌حواس‌پرتی، قدرتمند و استاندارد.</p></div><div className="facility-grid"><article className="facility-card facility-large"><div className="facility-image facility-image-1"/><div><span>۰۱ / تمرین قدرتی</span><h3>برای وزنه‌های<br/>سنگین‌تر.</h3></div></article><article className="facility-card"><div className="facility-image facility-image-2"/><div><span>۰۲ / وزنه آزاد</span><h3>آزادی حرکت.</h3></div></article><article className="facility-card facility-dark"><div className="facility-grid-icon">✦</div><span>۰۳ / فضای اختصاصی</span><h3>فضایی که<br/>حواست را جمع می‌کند.</h3><button onClick={onRequest}>عضویت در Fit Land Gym ←</button></article><article className="facility-card"><div className="facility-image facility-image-3"/><div><span>۰۴ / هوازی</span><h3>انرژی بیشتر.</h3></div></article></div></section>
    <section className="public-section proof-section"><div className="proof-image"/><div className="proof-content"><div className="eyebrow">تجربه‌ای که می‌ماند</div><h2>باشگاه فقط جایی برای تمرین نیست.</h2><p>جایی است که هر بار واردش می‌شوی، به خودت یادآوری می‌کنی برای چه شروع کردی. از اولین گرم کردن تا آخرین تکرار، همه‌چیز برای یک تجربه بهتر طراحی شده.</p><div className="signature"><div className="signature-avatar">FL</div><div><strong>تیم Fit Land Gym</strong><span>همراه مسیر تو، هر روز</span></div></div></div></section>
    <section id="membership" className="public-section pricing-section"><div className="center-intro"><div className="eyebrow">یک قدم تا شروع</div><h2>پلن مناسب خودت را<br/><em>انتخاب کن.</em></h2><p>بدون قرارداد پیچیده. بدون هزینه پنهان. فقط یک انتخاب برای جدی‌تر تمرین کردن.</p></div><div className="plans"><Plan name="یک‌ماهه" price="۲,۸۰۰,۰۰۰" detail="برای شروع بدون تعهد" onClick={onRequest}/><Plan featured name="سه‌ماهه" price="۷,۵۰۰,۰۰۰" detail="محبوب‌ترین انتخاب اعضا" onClick={onRequest}/><Plan name="شش‌ماهه" price="۱۳,۵۰۰,۰۰۰" detail="برای ساختن یک عادت واقعی" onClick={onRequest}/></div></section>
    <section id="faq" className="public-section faq-section"><div className="faq-side"><div className="eyebrow">سوالات متداول</div><h2>هنوز سوالی<br/><em>داری؟</em></h2><p>اگر پاسخ سوالت اینجا نبود، با ما تماس بگیر. خوشحال می‌شویم راهنمایی‌ات کنیم.</p><a className="text-link" href="tel:44085217">تماس با Fit Land Gym ←</a></div><div className="faq-list">{faqs.map((faq, index) => <div className={`faq-item ${activeFaq === index ? 'open' : ''}`} key={faq}><button onClick={() => setActiveFaq(activeFaq === index ? -1 : index)}><span>{faq}</span><b>{activeFaq === index ? '−' : '+'}</b></button>{activeFaq === index && <p>{index === 0 ? 'نه؛ تیم ما در اولین جلسه مسیر مناسب سطح و هدف تو را مشخص می‌کند.' : index === 1 ? 'هر روز از ۶ صبح تا ۲۳:۳۰ در کنار شما هستیم.' : 'بله، قبل از تصمیم‌گیری می‌توانی از مجموعه بازدید کنی.'}</p>}</div>)}</div></section>
    <section className="public-contact public-section" id="contact"><div><div className="eyebrow">موقعیت و تماس</div><h2>شروع مسیر،<br/><em>نزدیک‌تر از چیزی است که فکر می‌کنی.</em></h2></div><div className="contact-grid"><a className="contact-card" href="https://maps.google.com/?q=اشرفی+اصفهانی+کوچه+گلستان+۱۴" target="_blank" rel="noreferrer"><span className="contact-icon">⌖</span><strong>آدرس باشگاه</strong><p>اشرفی اصفهانی جنوب، پایین‌تر از مرزداران، کوچه گلستان ۱۴، برج نگین رضا</p><small>مشاهده روی نقشه ←</small></a><a className="contact-card" href="tel:44085217"><span className="contact-icon">◌</span><strong>تماس با پذیرش</strong><p>۴۴۰۸۵۲۱۷<br/>۰۹۱۲۷۱۷۰۵۳۵</p><small>تماس مستقیم ←</small></a><div className="contact-card contact-hours"><span className="contact-icon">◷</span><strong>ساعات کاری</strong><p>هر روز<br/>از ۶ صبح تا ۲۳:۳۰</p><small>ویژه آقایان</small></div></div></section><section className="public-cta"><div><div className="eyebrow eyebrow-light">آماده‌ای؟</div><h2>نسخه قوی‌تر تو<br/>منتظر شروع توست.</h2></div><Button onClick={onRequest}>درخواست عضویت <span>←</span></Button></section>
  </main><footer className="public-footer"><div className="brand-lockup"><div className="brand-mark">FL</div><div><strong>Fit Land Gym</strong><span>باشگاه بدنسازی آقایان</span></div></div><span>📍 اشرفی اصفهانی جنوب، پایین‌تر از مرزداران، کوچه گلستان ۱۴، برج نگین رضا</span><span>🕕 آقایان ۰۶ تا ۲۳:۳۰ · ☎️ ۴۴۰۸۵۲۱۷ · ۰۹۱۲۷۱۷۰۵۳۵</span></footer></div>
}
function Plan({ name, price, detail, featured = false, onClick }: { name: string; price: string; detail: string; featured?: boolean; onClick: () => void }) { return <article className={`plan ${featured ? 'plan-featured' : ''}`}>{featured && <span className="plan-popular">پیشنهاد Fit Land Gym</span>}<span className="plan-name">{name}</span><h3>{price}<small> تومان</small></h3><span className="plan-detail">{detail}</span><div className="plan-divider"/><ul><li>دسترسی کامل به باشگاه</li><li>رختکن و کمد اختصاصی</li><li>پیگیری و پشتیبانی عضویت</li></ul><Button variant={featured ? 'primary' : 'ghost'} onClick={onClick} full>انتخاب پلن <span>←</span></Button></article> }

function AdminShell({ screen, onNavigate, onPublic, children, onMemberPortal, toasts }: { screen: Screen; onNavigate: (screen: Screen) => void; onPublic: () => void; children: ReactNode; onMemberPortal: () => void; toasts: Toast[] }) {
  const [menuOpen, setMenuOpen] = useState(false); const navigateFromMenu = (next: Screen) => { setMenuOpen(false); onNavigate(next) }
  const title = ({ admin: 'داشبورد', members: 'اعضا', memberships: 'عضویت‌ها', payments: 'پرداخت‌ها', attendance: 'حضور و غیاب', leads: 'درخواست‌ها', reports: 'گزارش‌ها' } as Record<string, string>)[screen] || 'داشبورد'
  return <div className={`admin-shell ${menuOpen ? 'menu-open' : ''}`}><button className="drawer-backdrop" aria-label="بستن منو" onClick={() => setMenuOpen(false)}/><aside className="sidebar"><div className="sidebar-close-row"><span>منوی مدیریت</span><button onClick={() => setMenuOpen(false)} aria-label="بستن منو">×</button></div><div className="sidebar-brand"><div className="brand-mark">FL</div><div><strong>Fit Land Gym</strong><span>مدیریت باشگاه</span></div></div><div className="workspace-switch"><div className="workspace-icon">FL</div><div><strong>باشگاه Fit Land Gym</strong><span>فضای مدیریت</span></div><b>⌄</b></div><nav className="side-nav">{navGroups.map(group => <div key={group.label}><span className="nav-label">{group.label}</span>{group.items.map(item => <button className={screen === item.id ? 'active' : ''} key={item.id} onClick={() => navigateFromMenu(item.id as Screen)}><Icon>{item.icon}</Icon>{item.label}{item.id === 'leads' && <span className="nav-count">۴</span>}</button>)}</div>)}</nav><div className="sidebar-bottom"><button onClick={() => { setMenuOpen(false); onMemberPortal() }}><Icon>◉</Icon>نمایش پنل عضو</button><button onClick={() => { setMenuOpen(false); onPublic() }}><Icon>↗</Icon>مشاهده سایت</button><div className="user-row"><div className="user-avatar">ر</div><div><strong>رضا دشتی</strong><span>مدیریت Fit Land Gym</span></div><span>•••</span></div></div></aside><main className="admin-main"><header className="admin-topbar"><button className="mobile-menu-button" onClick={() => setMenuOpen(true)} aria-label="باز کردن منوی مدیریت"><span/><span/><span/></button><div className="mobile-brand"><div className="brand-mark">FL</div><strong>Fit Land Gym</strong></div><div className="breadcrumbs"><span>Fit Land Gym</span><b>›</b><strong>{title}</strong></div><div className="demo-switcher"><button onClick={onPublic}>سایت باشگاه</button><button className="active">پنل مدیریت</button><button onClick={onMemberPortal}>پنل عضو</button></div><div className="topbar-actions"><button className="top-icon" aria-label="جستجو">⌕</button><button className="top-icon notification" aria-label="اعلان‌ها">♧<i/></button><div className="top-date">پنجشنبه، ۵ شهریور ۱۴۰۵</div></div></header><div className="admin-content">{children}</div></main>{toasts.length > 0 && <div className="toast-stack">{toasts.map(toast => <div className={`toast toast-${toast.type || 'success'}`} key={toast.id}><span>✓</span>{toast.message}</div>)}</div>}</div>
}

function Kpi({ label, value, change, positive, warning, icon }: { label: string; value: string; change: string; positive?: boolean; warning?: boolean; icon: string }) { return <div className={`kpi-card ${warning ? 'kpi-warning' : ''}`}><div className="kpi-top"><span className="kpi-icon">{icon}</span><span className="kpi-menu">•••</span></div><span className="kpi-label">{label}</span><strong>{value}</strong><span className={`kpi-change ${positive ? 'positive' : warning ? 'warning' : ''}`}>{positive && '↑ '}{change}</span></div> }
function AttendanceChart({ attendance }: { attendance?: Attendance[] }) { const values = attendance ? [84, 112, 138, 121, 151, 176, Math.max(94, attendance.filter(item => item.date.includes('امروز')).length)] : [84, 112, 138, 121, 151, 176, 94]; const days = ['شنبه', 'یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه']; return <div className="bar-chart">{values.map((value, i) => <div className={`bar-column ${i === 5 ? 'today' : ''}`} key={days[i]}><span>{value}</span><div className="bar-track"><i style={{ height: `${value / 190 * 100}%` }}/></div><small>{days[i]}</small></div>)}</div> }
function Attention({ label, value, note, icon, onClick }: { label: string; value: string; note: string; icon: string; onClick: () => void }) { return <button className="attention-row" onClick={onClick}><span className="attention-icon">{icon}</span><span><strong>{label}</strong><small>{note}</small></span><b>{value}</b><span className="attention-arrow">←</span></button> }
function Activity({ icon, color, title, desc, time }: { icon: string; color: string; title: string; desc: string; time: string }) { return <div className="activity-row"><span className={`activity-icon ${color}`}>{icon}</span><div><strong>{title}</strong><span>{desc}</span></div><small>{time}</small></div> }
function RiskBadge({ level }: { level: RiskLevel }) { return <span className={`risk-badge risk-${level.replaceAll(' ', '-')}`}><i/>{level}</span> }

function Dashboard({ members, payments, attendance, leads, onNavigate, onFollowUp, onMember, onAdd, onPayment, onCheckin }: { members: Member[]; payments: Payment[]; attendance: Attendance[]; leads: Lead[]; onNavigate: (s: Screen) => void; onFollowUp: (m: Member) => void; onMember: (m: Member) => void; onAdd: () => void; onPayment: () => void; onCheckin: () => void }) {
  const active = members.filter(m => m.status === 'فعال').length, expiring = members.filter(m => m.status === 'رو به پایان').length, debt = members.filter(m => m.status === 'بدهکار').length, inactive = members.filter(m => m.status === 'غیرفعال' || m.status === 'منقضی').length
  const riskMembers = members.filter(m => m.risk === 'در معرض ریزش' || m.risk === 'نیازمند توجه').slice(0, 3)
  const newRegistrations = leads.filter(l => l.created.includes('امروز')).length
  const monthRevenue = payments.filter(p => p.status === 'پرداخت موفق').reduce((sum, p) => sum + p.amount, 0)
  return <><PageHeader eyebrow="پنجشنبه، ۵ شهریور ۱۴۰۵" title="سلام رضا 👋" description="در کمتر از ۱۰ ثانیه ببین امروز در Fit Land Gym چه خبر است." action={<Button onClick={onAdd}>+ افزودن عضو</Button>}/><section className="insight-banner"><div className="insight-symbol">✦</div><div><strong>امروز تمرکز روی نگهداشت است</strong><p>{expiring} عضویت در آستانه پایان هستند؛ پیگیری امروز می‌تواند از ریزش جلوگیری کند.</p></div><button onClick={() => onNavigate('memberships')}>مشاهده لیست ←</button></section><div className="kpi-grid"><Kpi label="اعضای فعال" value={String(active)} change="۸.۴٪ نسبت به ماه قبل" positive icon="◎"/><Kpi label="ثبت‌نام جدید" value={String(newRegistrations)} change="۲۱٪ رشد" positive icon="✦"/><Kpi label="درآمد این ماه" value={`${Math.round(monthRevenue / 1000000)}M`} change="۱۲.۶٪ رشد" positive icon="↙"/><Kpi label="عضویت رو به پایان" value={String(expiring)} change="نیاز به پیگیری" warning icon="◷"/></div><section className="pulse-strip"><div><span>ورود امروز</span><strong>{attendance.filter(item => item.date.includes('امروز')).length}</strong><small>در حال افزایش</small></div><div><span>ثبت‌نام</span><strong>{newRegistrations}</strong><small>امروز</small></div><div><span>تمدید</span><strong>{payments.filter(p => p.type === 'تمدید عضویت').length}</strong><small>این ماه</small></div><div><span>پرداخت معوق</span><strong className="orange-text">{debt}</strong><small>نیاز به تماس</small></div></section><div className="dashboard-grid"><div className="panel attendance-panel"><div className="panel-head"><div><span className="panel-kicker">وضعیت امروز</span><h2>روند حضور اعضا</h2></div><span className="panel-value">۷ روز گذشته</span></div><div className="chart-legend"><span><i className="legend-lime"/> ورود اعضا</span><strong>{attendance.length}<small> ورود ثبت‌شده</small></strong></div><AttendanceChart attendance={attendance}/></div><div className="panel peak-card"><div className="panel-head"><div><span className="panel-kicker">تحلیل رفتار اعضا</span><h2>ساعات پرتردد</h2></div><span className="peak-label">۱۸—۲۰</span></div><p>بیشترین مراجعه اعضا در این بازه اتفاق می‌افتد.</p><div className="peak-bars"><div><i style={{ height: '31%' }}/><span>۰۶</span></div><div><i style={{ height: '48%' }}/><span>۱۰</span></div><div><i style={{ height: '38%' }}/><span>۱۴</span></div><div className="hot"><i style={{ height: '86%' }}/><span>۱۸</span></div><div className="hot"><i style={{ height: '74%' }}/><span>۲۰</span></div><div><i style={{ height: '42%' }}/><span>۲۲</span></div></div><strong className="peak-foot">۴۴٪ از ورودهای روزانه <small>در ساعات عصر</small></strong></div></div><div className="retention-heading"><div><span className="eyebrow">مزیت رقابتی Fit Land</span><h2>اعضای نیازمند توجه</h2><p>سیستم قبل از ریزش، فرصت اقدام را به مدیر نشان می‌دهد.</p></div><button className="text-link" onClick={() => onNavigate('members')}>مشاهده همه ←</button></div><div className="retention-cards"><Attention label="تمدید" value={String(expiring)} note="در ۷ روز آینده" icon="◷" onClick={() => onNavigate('memberships')}/><Attention label="غیرفعال" value={String(inactive)} note="بیش از ۷ روز بدون ورود" icon="◎" onClick={() => onNavigate('members')}/><Attention label="بدهکار" value={String(debt)} note="در انتظار پرداخت" icon="↙" onClick={() => onNavigate('payments')}/></div><div className="dashboard-grid lower-grid"><div className="panel risk-panel"><div className="panel-head"><div><span className="panel-kicker">Smart retention insight</span><h2>اعضای در معرض ریزش</h2></div><button className="text-link" onClick={() => onNavigate('members')}>مشاهده همه ←</button></div><div className="risk-list">{riskMembers.map(member => <div className="risk-row" key={member.id}><Avatar member={member}/><button className="risk-info" onClick={() => onMember(member)}><strong>{member.name}</strong><span>{member.riskReason}</span></button><div className="risk-meta"><RiskBadge level={member.risk}/><span>{member.expiry}</span></div><button className="row-action" onClick={() => onFollowUp(member)}>پیگیری</button></div>)}</div></div><div className="panel renewal-forecast"><div className="panel-head"><div><span className="panel-kicker">پیش‌بینی تمدید</span><h2>وضعیت تمدید این هفته</h2></div><span className="forecast-total">{expiring + 25} عضو</span></div><div className="forecast-row"><span><i className="forecast-dot ready"/> آماده تمدید</span><strong>۱۸</strong></div><div className="forecast-row"><span><i className="forecast-dot follow"/> نیازمند پیگیری</span><strong>۹</strong></div><div className="forecast-row"><span><i className="forecast-dot risk"/> در معرض ریزش</span><strong>۴</strong></div><div className="forecast-progress"><i style={{ width: '58%' }}/></div><small>فرصت بالقوه حفظ درآمد این هفته</small></div></div><div className="quick-action-panel"><div><span className="panel-kicker">کارهای روزانه</span><h2>عملیات سریع</h2></div><div className="quick-admin-actions"><button onClick={onAdd}><span>＋</span><strong>افزودن عضو</strong><small>ثبت سریع عضو جدید</small></button><button onClick={onPayment}><span>↙</span><strong>ثبت پرداخت</strong><small>به‌روزرسانی حساب عضو</small></button><button onClick={onCheckin}><span>▦</span><strong>ثبت ورود</strong><small>QR یا پذیرش</small></button><button onClick={() => onNavigate('leads')}><span>✦</span><strong>درخواست‌های جدید</strong><small>{leads.filter(l => l.status === 'جدید').length} مورد در انتظار</small></button></div></div><div className="dashboard-grid lower-grid"><div className="panel activity-panel"><div className="panel-head"><div><span className="panel-kicker">آخرین فعالیت</span><h2>رویدادهای امروز</h2></div><button className="text-link" onClick={() => onNavigate('attendance')}>همه رویدادها ←</button></div><div className="activity-list"><Activity icon="↙" color="lime" title="پرداخت جدید ثبت شد" desc={`${members[4]?.name} · ۲,۸۰۰,۰۰۰ تومان`} time="۲ دقیقه پیش"/><Activity icon="◎" color="blue" title="ورود عضو ثبت شد" desc="محمد رضایی · از طریق QR" time="۱۸:۴۲"/><Activity icon="✦" color="orange" title="درخواست عضویت جدید" desc={`${leads[0]?.name} · پلن ${leads[0]?.plan}`} time="۰۹:۲۴"/></div></div><div className="panel sales-story"><span className="panel-kicker">داستان محصول</span><h2>جذب، مدیریت، نگهداشت.</h2><p>تمام داده‌ها به هم متصل‌اند تا مدیر باشگاه از جذب اولیه تا تمدید بعدی یک تصویر کامل داشته باشد.</p><div><b>۱</b> سایت و درخواست عضویت <b>۲</b> عملیات روزانه <b>۳</b> پیگیری و تمدید</div></div></div></>
}

function MembersPage({ members, onMember, onAdd, onToast }: { members: Member[]; onMember: (m: Member) => void; onAdd: () => void; onToast: (message: string) => void }) { const [query, setQuery] = useState(''); const [filter, setFilter] = useState('همه'); const filters = ['همه', 'فعال', 'رو به پایان', 'منقضی', 'بدهکار', 'غیرفعال']; const filtered = members.filter(m => (filter === 'همه' || m.status === filter) && `${m.name} ${m.phone}`.includes(query)); return <><PageHeader eyebrow="مدیریت اعضا" title="اعضای باشگاه" description={`${members.length} عضو نمونه واقعی‌نما در سیستم Fit Land Gym ثبت شده‌اند.`} action={<Button onClick={onAdd}>+ افزودن عضو</Button>}/><div className="toolbar"><div className="search-box"><span>⌕</span><input value={query} onChange={e => setQuery(e.target.value)} placeholder="جستجوی نام، شماره موبایل..."/></div><button className="filter-date" onClick={() => onToast('فیلتر تاریخ در نسخه Demo آماده است')}>همه تاریخ‌ها⌄</button><button className="export-button" onClick={() => onToast('خروجی اعضا آماده شد')}>↓ خروجی گرفتن</button></div><div className="filter-tabs">{filters.map(item => <button className={filter === item ? 'active' : ''} onClick={() => setFilter(item)} key={item}>{item}{item === 'رو به پایان' && <small>{members.filter(m => m.status === item).length}</small>}</button>)}</div><div className="panel table-panel"><div className="table-summary"><span>{filtered.length} عضو نمایش داده می‌شود</span><span>آخرین همگام‌سازی: همین حالا</span></div>{filtered.length === 0 ? <EmptyState title="عضوی پیدا نشد"/> : <div className="table-scroll"><table><thead><tr><th>عضو</th><th>شماره تماس</th><th>وضعیت</th><th>ریسک</th><th>عضویت</th><th>تاریخ انقضا</th><th>آخرین حضور</th></tr></thead><tbody>{filtered.map(member => <tr key={member.id}><td><button className="member-cell" onClick={() => onMember(member)}><Avatar member={member} size="sm"/><span><strong>{member.name}</strong><small>عضویت از {member.joined}</small></span></button></td><td className="phone-cell">{member.phone}</td><td><StatusBadge status={member.status}/></td><td><RiskBadge level={member.risk}/></td><td>{member.plan}</td><td>{member.expiry}</td><td>{member.lastVisit}</td></tr>)}</tbody></table></div>}</div></> }

function MembershipsPage({ members, memberships, onRenew }: { members: Member[]; memberships: Membership[]; onRenew: (m: Member) => void }) { const [tab, setTab] = useState('همه'); const statuses = ['همه', 'فعال', 'رو به پایان', 'منقضی']; const filtered = memberships.filter(m => tab === 'همه' || m.status === tab); return <><PageHeader eyebrow="مدیریت درآمد تکرارشونده" title="عضویت‌ها" description="وضعیت تمام اشتراک‌های باشگاه را در یک نگاه ببین." action={<Button onClick={() => onRenew(members.find(m => m.status === 'رو به پایان') || members[0])}>تمدید عضویت</Button>}/><div className="mini-kpis"><div><span>کل عضویت‌ها</span><strong>{memberships.length}</strong></div><div><span>فعال</span><strong className="lime-text">{members.filter(m => m.status === 'فعال').length}</strong></div><div><span>رو به پایان</span><strong className="orange-text">{members.filter(m => m.status === 'رو به پایان').length}</strong></div><div><span>منقضی</span><strong className="red-text">{members.filter(m => m.status === 'منقضی').length}</strong></div></div><div className="filter-tabs wide-tabs">{statuses.map(s => <button key={s} className={tab === s ? 'active' : ''} onClick={() => setTab(s)}>{s}</button>)}</div><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>عضو</th><th>پلن</th><th>شروع</th><th>پایان</th><th>مبلغ</th><th>وضعیت</th><th/></tr></thead><tbody>{filtered.map(item => { const member = members.find(m => m.id === item.memberId); return member ? <tr key={item.id}><td><span className="member-cell"><Avatar member={member} size="sm"/><strong>{member.name}</strong></span></td><td>{item.plan}</td><td>{item.start}</td><td>{item.end}</td><td>{item.price.toLocaleString('fa-IR')}</td><td><StatusBadge status={item.status}/></td><td><button className="row-action" onClick={() => onRenew(member)}>تمدید</button></td></tr> : null})}</tbody></table></div></div></> }

function PaymentsPage({ members, payments, onPayment, onToast }: { members: Member[]; payments: Payment[]; onPayment: () => void; onToast: (message: string) => void }) { const successful = payments.filter(p => p.status === 'پرداخت موفق'); const revenue = successful.reduce((sum, p) => sum + p.amount, 0); return <><PageHeader eyebrow="گردش مالی باشگاه" title="پرداخت‌ها" description="درآمد و بدهی‌ها را شفاف و قابل پیگیری نگه دار." action={<Button onClick={onPayment}>+ ثبت پرداخت</Button>}/><div className="mini-kpis"><div><span>درآمد این ماه</span><strong>{Math.round(revenue / 1000000)}M</strong><small className="positive-text">↑ ۱۲.۶٪</small></div><div><span>پرداخت‌های موفق</span><strong>{successful.length}</strong><small className="positive-text">↑ ۸.۴٪</small></div><div><span>در انتظار پرداخت</span><strong className="orange-text">{members.filter(m => m.status === 'بدهکار').length}</strong><small>نیاز به پیگیری</small></div><div><span>میانگین پرداخت</span><strong>{Math.round(revenue / Math.max(successful.length, 1) / 100000) / 10}M</strong><small>در هر تراکنش</small></div></div><div className="toolbar"><div className="search-box"><span>⌕</span><input placeholder="جستجوی نام عضو..."/></div><button className="filter-date" onClick={() => onToast('فیلتر شهریور ۱۴۰۵ فعال است')}>شهریور ۱۴۰۵⌄</button><button className="export-button" onClick={() => onToast('گزارش مالی دانلود شد')}>↓ خروجی گرفتن</button></div><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>عضو</th><th>مبلغ</th><th>نوع پرداخت</th><th>تاریخ</th><th>روش</th><th>وضعیت</th></tr></thead><tbody>{payments.slice(0, 12).map(payment => { const member = members.find(m => m.id === payment.memberId); return member ? <tr key={payment.id}><td><span className="member-cell"><Avatar member={member} size="sm"/><strong>{member.name}</strong></span></td><td><strong>{payment.amount.toLocaleString('fa-IR')}</strong> تومان</td><td>{payment.type}</td><td>{payment.date}</td><td>{payment.method}</td><td><StatusBadge status={payment.status}/></td></tr> : null})}</tbody></table></div></div></> }

function AttendancePage({ members, attendance, onCheckin }: { members: Member[]; attendance: Attendance[]; onCheckin: () => void }) { const today = attendance.filter(item => item.date.includes('امروز')).length; return <><PageHeader eyebrow="ورود و خروج اعضا" title="حضور و غیاب" description="رفت‌وآمد اعضا و ساعت‌های پرتردد را دقیق‌تر بشناس." action={<Button onClick={onCheckin}>+ ثبت ورود</Button>}/><div className="mini-kpis"><div><span>ورود امروز</span><strong>{today}</strong><small className="positive-text">↑ ۱۶٪ نسبت به دیروز</small></div><div><span>این هفته</span><strong>{attendance.length}</strong><small>میانگین روزانه ۱۰۶</small></div><div><span>این ماه</span><strong>{attendance.length * 3}</strong><small className="positive-text">↑ ۹.۲٪</small></div><div><span>ساعت پرتردد</span><strong>۱۸:۰۰</strong><small>۴۴٪ ورودها</small></div></div><div className="dashboard-grid"><div className="panel attendance-panel"><div className="panel-head"><div><span className="panel-kicker">روند هفتگی</span><h2>ورود اعضا</h2></div><span className="panel-value">این ماه</span></div><AttendanceChart attendance={attendance}/></div><div className="panel peak-card"><div className="panel-head"><div><span className="panel-kicker">تحلیل هوشمند</span><h2>ساعات پرتردد</h2></div></div><p>۴۴٪ از ورودها بین ساعت ۱۸ تا ۲۲ ثبت شده‌اند.</p><div className="peak-list"><div><span>۰۶ تا ۱۰</span><i style={{ width: '42%' }}/><b>۱۸٪</b></div><div><span>۱۰ تا ۱۴</span><i style={{ width: '28%' }}/><b>۱۲٪</b></div><div><span>۱۴ تا ۱۸</span><i style={{ width: '58%' }}/><b>۲۶٪</b></div><div><span>۱۸ تا ۲۲</span><i style={{ width: '82%' }}/><b>۴۴٪</b></div></div></div></div><div className="panel table-panel"><div className="panel-head"><div><span className="panel-kicker">آخرین ورودها</span><h2>ترددهای اخیر</h2></div></div><div className="table-scroll"><table><thead><tr><th>عضو</th><th>تاریخ</th><th>زمان ورود</th><th>روش ورود</th><th>وضعیت</th></tr></thead><tbody>{attendance.slice(0, 10).map(item => { const member = members.find(m => m.id === item.memberId); return member ? <tr key={item.id}><td><span className="member-cell"><Avatar member={member} size="sm"/><strong>{member.name}</strong></span></td><td>{item.date}</td><td>{item.time}</td><td><span className="method">▦ {item.method}</span></td><td><span className="checkin-status">حضور ثبت شد</span></td></tr> : null})}</tbody></table></div></div></> }

function LeadsPage({ leads, onConvert, onFollow, onToast }: { leads: Lead[]; onConvert: (lead: Lead) => void; onFollow: (lead: Lead) => void; onToast: (message: string) => void }) { const [tab, setTab] = useState('همه'); const tabs = ['همه', 'جدید', 'در حال پیگیری', 'تبدیل شده']; const filtered = leads.filter(l => tab === 'همه' || l.status === tab); return <><PageHeader eyebrow="قیف جذب عضو" title="درخواست‌های عضویت" description="هر درخواست، یک فرصت برای ساختن رابطه‌ای بلندمدت است." action={<Button onClick={() => onToast('لینک فرم عضویت کپی شد')}>اشتراک‌گذاری فرم ←</Button>}/><div className="lead-board-stats"><div><span>کل درخواست‌ها</span><strong>{leads.length}</strong></div><div><span>در انتظار تماس</span><strong className="orange-text">{leads.filter(l => l.status !== 'تبدیل شده').length}</strong></div><div><span>نرخ تبدیل</span><strong className="lime-text">{Math.round(leads.filter(l => l.status === 'تبدیل شده').length / Math.max(leads.length, 1) * 100)}٪</strong></div></div><div className="filter-tabs wide-tabs">{tabs.map(s => <button key={s} className={tab === s ? 'active' : ''} onClick={() => setTab(s)}>{s}{s === 'جدید' && <small>{leads.filter(l => l.status === 'جدید').length}</small>}</button>)}</div><div className="lead-grid">{filtered.map(lead => <article className="lead-card" key={lead.id}><div className="lead-card-top"><div className="lead-avatar">{lead.name.slice(0, 1)}</div><StatusBadge status={lead.status}/></div><h3>{lead.name}</h3><span>{lead.phone}</span><div className="lead-meta"><span>پلن موردنظر</span><strong>{lead.plan}</strong></div><div className="lead-meta"><span>ثبت درخواست</span><strong>{lead.created}</strong></div><div className="lead-actions"><Button variant="ghost" onClick={() => onFollow(lead)}>پیگیری</Button>{lead.status !== 'تبدیل شده' && <Button onClick={() => onConvert(lead)}>تبدیل به عضو</Button>}</div></article>)}</div>{filtered.length === 0 && <EmptyState/>}</> }

function ReportsPage({ members, payments, leads }: { members: Member[]; payments: Payment[]; leads: Lead[] }) { const success = payments.filter(p => p.status === 'پرداخت موفق'); return <><PageHeader eyebrow="داده برای تصمیم بهتر" title="گزارش‌ها" description="ریتم رشد Fit Land Gym را با داده‌های متصل دنبال کن." action={<Button variant="ghost" onClick={() => window.print()}>↓ دانلود گزارش</Button>}/><div className="reports-grid"><div className="report-card report-highlight"><span>رشد خالص اعضا</span><strong>+{leads.filter(l => l.status === 'تبدیل شده').length + 20}</strong><small>در ۳۰ روز گذشته</small><div className="sparkline"><i/><i/><i/><i/><i/><i/><i/><i/></div></div><div className="report-card"><span>میانگین ماندگاری</span><strong>۴.۸ ماه</strong><small className="positive-text">↑ ۰.۶ ماه</small><div className="report-bars"><i style={{ height: '38%' }}/><i style={{ height: '51%' }}/><i style={{ height: '64%' }}/><i style={{ height: '72%' }}/><i style={{ height: '86%' }}/></div></div><div className="report-card"><span>نرخ تمدید</span><strong>۷۲٪</strong><small className="positive-text">↑ ۸٪ نسبت به ماه قبل</small><div className="circle-progress"><b>۷۲٪</b></div></div></div><div className="dashboard-grid lower-grid"><div className="panel"><div className="panel-head"><div><span className="panel-kicker">گزارش مدیریتی</span><h2>سه نکته مهم این ماه</h2></div></div><div className="report-insights"><div><span>۰۱</span><p>بیشترین ورود اعضا بین ساعت ۱۸ تا ۲۲ اتفاق می‌افتد.</p></div><div><span>۰۲</span><p>اعضای پلن شش‌ماهه، ۲.۴ برابر بیشتر تمدید می‌کنند.</p></div><div><span>۰۳</span><p>{members.filter(m => m.risk === 'در معرض ریزش').length} عضو نیازمند برنامه بازگشت و پیگیری هستند.</p></div></div></div><div className="panel report-side"><span className="panel-kicker">خلاصه عملکرد</span><h2>{success.length} پرداخت موفق ثبت شده.</h2><p>{leads.length} درخواست از سایت وارد شده و داده‌ها بین سه بخش محصول مشترک‌اند.</p><div className="system-status"><i/> تمام سرویس‌های Demo فعال هستند</div></div></div></> }

function MemberProfile({ member, payments, attendance, timeline, onBack, onFollowUp, onPayment, onRenew }: { member: Member; payments: Payment[]; attendance: Attendance[]; timeline: TimelineItem[]; onBack: () => void; onFollowUp: () => void; onPayment: () => void; onRenew: () => void }) { const memberPayments = payments.filter(p => p.memberId === member.id); const memberAttendance = attendance.filter(a => a.memberId === member.id); const events = timeline.filter(t => t.memberId === member.id).slice(-6).reverse(); return <><button className="back-link" onClick={onBack}>→ بازگشت به اعضا</button><div className="profile-header panel"><div className="profile-identity"><Avatar member={member} size="lg"/><div><div className="eyebrow">پرونده عضو · Fit Land Gym</div><h1>{member.name}</h1><span>{member.phone} · عضو از {member.joined}</span></div></div><div className="profile-actions"><RiskBadge level={member.risk}/><StatusBadge status={member.status}/><Button variant="ghost" onClick={onFollowUp}>پیگیری عضو</Button></div></div><div className="profile-grid"><div className="profile-main"><div className="profile-info-grid panel"><Info label="نوع عضویت" value={member.plan}/><Info label="تاریخ انقضا" value={member.expiry}/><Info label="شماره کمد" value={member.locker}/><Info label="جلسات این ماه" value={`${member.visits} جلسه`}/></div><div className="panel profile-risk-explanation"><div><RiskBadge level={member.risk}/><h2>{member.riskReason}</h2><p>{member.risk === 'پایدار' ? 'رفتار این عضو منظم است و نشانه‌ای از ریزش دیده نمی‌شود.' : 'این insight بر اساس وضعیت عضویت، آخرین حضور و پرداخت‌های عضو محاسبه شده است.'}</p></div><Button variant="ghost" onClick={onFollowUp}>اقدام پیشنهادی ←</Button></div><div className="panel"><div className="panel-head"><div><span className="panel-kicker">حضور و غیاب</span><h2>ریتم حضور عضو</h2></div><span className="panel-value">{memberAttendance.length} ورود ثبت‌شده</span></div><div className="mini-calendar"><div className="calendar-head"><b>شهریور ۱۴۰۵</b><span>‹　›</span></div><div className="calendar-days">{['ش','ی','د','س','چ','پ','ج'].map(d => <b key={d}>{d}</b>)}{Array.from({ length: 30 }, (_, i) => <span className={(i % 3 !== 0 && i < 25) ? 'visited' : ''} key={i}>{i + 1}</span>)}</div></div></div><div className="panel payment-highlight"><div><span className="panel-kicker">پرداخت‌های عضو</span><h2>{memberPayments.length ? memberPayments[memberPayments.length - 1].amount.toLocaleString('fa-IR') : '۰'} تومان</h2><p>{memberPayments.length ? 'آخرین پرداخت · ' + memberPayments[memberPayments.length - 1].date : 'هنوز پرداختی ثبت نشده'}</p></div><button className="payment-icon" onClick={onPayment}>↙</button></div></div><aside className="profile-side"><div className="panel insight-card"><div className="insight-symbol">✦</div><span className="panel-kicker">نگهداشت هوشمند</span><h2>{member.risk === 'پایدار' ? 'این عضو در مسیر خوبی است.' : 'این عضو به یک پیگیری دوستانه نیاز دارد.'}</h2><p>{member.riskReason}؛ یک پیام به‌موقع می‌تواند رابطه را حفظ کند.</p><Button onClick={onFollowUp} full>پیگیری عضو <span>←</span></Button></div><div className="panel timeline-card"><div className="panel-head"><div><span className="panel-kicker">تاریخچه رابطه</span><h2>Timeline عضو</h2></div></div><div className="timeline">{events.length ? events.map(item => <div className="timeline-item" key={item.id}><i className={item.tone}/><div><strong>{item.title}</strong><span>{item.detail}</span></div><small>{item.date}</small></div>) : <EmptyState title="هنوز رویدادی ثبت نشده"/>}</div></div><div className="panel notes-card"><div className="panel-head"><h2>یادداشت‌های پذیرش</h2></div><p>هدف اصلی: افزایش حجم عضلانی</p><p>ترجیح می‌دهد عصرها تمرین کند.</p><button className="text-link" onClick={onRenew}>+ پیشنهاد تمدید عضویت</button></div></aside></div></> }
function Info({ label, value }: { label: string; value: string }) { return <div><span>{label}</span><strong>{value}</strong></div> }

function MemberPortal({ screen, member, memberPayments, onNavigate, onRenew, onCheckin }: { screen: Screen; member: Member; memberPayments: Payment[]; onNavigate: (s: Screen) => void; onRenew: () => void; onCheckin: () => void }) { return <div className="member-shell"><header className="member-topbar"><button className="member-brand" onClick={() => onNavigate('member-portal')}><span className="brand-mark">FL</span><strong>Fit Land Gym</strong></button><div className="member-top-actions"><button aria-label="اعلان‌ها">♧<i/></button><div className="member-avatar">م</div></div></header><main className="member-content">{screen === 'member-portal' ? <MemberOverview member={member} memberPayments={memberPayments} onNavigate={onNavigate} onRenew={onRenew} onCheckin={onCheckin}/> : screen === 'member-attendance' ? <MemberAttendance visits={member.visits} onBack={() => onNavigate('member-portal')}/> : screen === 'member-payments' ? <MemberPayments payments={memberPayments} onBack={() => onNavigate('member-portal')}/> : <MemberMembership member={member} onRenew={onRenew} onBack={() => onNavigate('member-portal')}/>}</main><nav className="member-bottom-nav"><button className={screen === 'member-portal' ? 'active' : ''} onClick={() => onNavigate('member-portal')}><span>⌂</span>خانه</button><button className={screen === 'member-attendance' ? 'active' : ''} onClick={() => onNavigate('member-attendance')}><span>◒</span>حضور من</button><button className="qr-nav" onClick={onCheckin}><span>▦</span><small>QR</small></button><button className={screen === 'member-payments' ? 'active' : ''} onClick={() => onNavigate('member-payments')}><span>↙</span>پرداخت‌ها</button><button className={screen === 'member-membership' ? 'active' : ''} onClick={() => onNavigate('member-membership')}><span>◎</span>عضویت</button></nav></div> }
function MemberOverview({ member, memberPayments, onNavigate, onRenew, onCheckin }: { member: Member; memberPayments: Payment[]; onNavigate: (s: Screen) => void; onRenew: () => void; onCheckin: () => void }) { const change = Math.round((member.visits - 11) / 11 * 100); return <><div className="member-welcome"><div><span className="member-kicker">پنجشنبه، ۵ شهریور</span><h1>سلام {member.name.split(' ')[0]} <span>👋</span></h1><p>امروز هم یک قدم نزدیک‌تری.</p></div><div className="member-avatar large">م</div></div><div className="member-status-card"><div className="status-card-head"><div><span>وضعیت عضویت</span><strong><i/> {member.status === 'منقضی' ? 'منقضی' : member.status === 'فعال' ? 'فعال' : member.status}</strong></div><button onClick={() => onNavigate('member-membership')}>جزئیات ←</button></div><div className="days-left"><strong>{member.status === 'فعال' ? '۱۷' : member.status === 'رو به پایان' ? '۵' : '—'}</strong><span>روز<br/>باقی‌مانده</span><div className="expiry-date">تا <b>{member.expiry}</b></div></div><div className="progress-line"><i style={{ width: member.status === 'فعال' ? '76%' : member.status === 'رو به پایان' ? '24%' : '4%' }}/></div></div><div className="member-section-head"><h2>خلاصه این ماه</h2><button onClick={() => onNavigate('member-attendance')}>مشاهده جزئیات ←</button></div><div className="member-stats"><div><span className="stat-icon lime">◒</span><strong>{member.visits}</strong><small>جلسه حضور</small><em>{change >= 0 ? `+${change}٪ نسبت به ماه قبل` : `${change}٪ نسبت به ماه قبل`}</em></div><div><span className="stat-icon orange">◷</span><strong>{member.lastVisit.includes('امروز') ? '۱۸:۴۲' : '—'}</strong><small>آخرین ورود</small><em>{member.lastVisit.includes('امروز') ? 'امروز' : member.lastVisit}</em></div><div><span className="stat-icon blue">↙</span><strong>{memberPayments.length}</strong><small>پرداخت موفق</small><em>این دوره</em></div></div><div className="member-progress-card"><div><span>پیشرفت حضور</span><strong>{change >= 0 ? '+' : ''}{change}٪</strong></div><p>رکورد شخصی: ۱۸ جلسه در یک ماه</p><div className="member-progress-bar"><i style={{ width: `${Math.min(100, member.visits / 18 * 100)}%` }}/></div></div><div className="member-section-head"><h2>دسترسی سریع</h2></div><div className="quick-actions"><button onClick={onCheckin}><span className="quick-icon lime">▦</span><strong>کد ورود من</strong><small>ورود سریع با QR</small><b>←</b></button><button onClick={() => onNavigate('member-attendance')}><span className="quick-icon blue">◒</span><strong>سوابق حضور</strong><small>تقویم این ماه</small><b>←</b></button><button onClick={() => onNavigate('member-payments')}><span className="quick-icon orange">↙</span><strong>پرداخت‌ها</strong><small>تاریخچه تراکنش‌ها</small><b>←</b></button></div><div className="member-section-head"><h2>دستاوردها</h2></div><div className="milestone-row"><span className="done">✓ ۱۰ جلسه</span><span className={member.visits >= 25 ? 'done' : ''}>{member.visits >= 25 ? '✓' : '○'} ۲۵ جلسه</span><span>○ ۵۰ جلسه</span></div><div className="motivation-card"><span>✦</span><div><strong>این ماه {change > 0 ? `${change}٪ بیشتر` : 'منظم'} به باشگاه آمدی.</strong><p>همین ریتم را حفظ کن؛ ثبات برنده است.</p></div></div><div className="member-notification"><span>●</span><div><strong>یادآوری عضویت</strong><p>{member.status === 'رو به پایان' ? 'عضویت شما ۷ روز دیگر به پایان می‌رسد.' : 'اعلان‌های مهم عضویت اینجا نمایش داده می‌شوند.'}</p></div></div><button className="member-renew-banner" onClick={onRenew}><span>عضویتت رو به پایان است؟</span><strong>تمدید عضویت <b>←</b></strong></button></> }
function MemberAttendance({ visits, onBack }: { visits: number; onBack: () => void }) { return <><div className="member-page-title"><button onClick={onBack}>‹</button><div><span>فعالیت من</span><h1>سوابق حضور</h1></div></div><div className="member-stat-highlight"><span>این ماه</span><strong>{visits} جلسه</strong><small>میانگین هر هفته: ۳.۵ جلسه</small></div><div className="member-calendar panel"><div className="calendar-head"><button aria-label="ماه قبل">‹</button><strong>شهریور ۱۴۰۵</strong><button aria-label="ماه بعد">›</button></div><div className="calendar-days big">{['ش','ی','د','س','چ','پ','ج'].map(d => <b key={d}>{d}</b>)}{Array.from({ length: 30 }, (_, i) => <span className={(i % 3 !== 0 && i < 25) ? 'visited' : i === 4 ? 'today' : ''} key={i}>{i + 1}</span>)}</div><div className="calendar-legend"><span><i className="visited-dot"/> حضور داشتی</span><span><i className="today-dot"/> امروز</span></div></div><div className="member-tip"><span>✦</span><p><strong>نکته Fit Land Gym</strong><br/>با ۴ جلسه حضور در هفته، ۲ برابر سریع‌تر به هدف می‌رسی.</p></div></> }
function MemberPayments({ payments, onBack }: { payments: Payment[]; onBack: () => void }) { const total = payments.reduce((sum, payment) => sum + payment.amount, 0); return <><div className="member-page-title"><button onClick={onBack}>‹</button><div><span>حساب مالی</span><h1>پرداخت‌های من</h1></div></div><div className="member-payment-total"><span>مجموع پرداخت این دوره</span><strong>{total.toLocaleString('fa-IR')} <small>تومان</small></strong><span className="positive-text">↑ بدون بدهی</span></div><div className="member-history"><h2>تاریخچه تراکنش‌ها</h2>{payments.slice(-5).reverse().map(payment => <div className="member-payment-row" key={payment.id}><span className="payment-check">✓</span><div><strong>{payment.date}</strong><small>{payment.type}</small></div><b>{payment.amount.toLocaleString('fa-IR')} <small>تومان</small></b><span className="paid-label">پرداخت موفق</span></div>)}</div></> }
function MemberMembership({ member, onRenew, onBack }: { member: Member; onRenew: () => void; onBack: () => void }) { return <><div className="member-page-title"><button onClick={onBack}>‹</button><div><span>حساب من</span><h1>عضویت من</h1></div></div><div className="membership-hero-card"><span className="plan-name">پلن {member.plan}</span><h2>عضویت {member.status === 'فعال' ? 'فعال' : member.status}</h2><div className="membership-hero-bottom"><div><small>تاریخ شروع</small><strong>{member.joined}</strong></div><div><small>تاریخ پایان</small><strong>{member.expiry}</strong></div><span className="active-ring">{member.status === 'فعال' ? '۱۷' : '—'}<br/><small>روز</small></span></div></div><div className="member-details panel"><h2>جزئیات عضویت</h2><Info label="مدت پلن" value={member.plan}/><Info label="شماره کمد" value={member.locker}/><Info label="دسترسی" value="کامل"/></div><button className="member-renew-primary" onClick={onRenew}>تمدید عضویت <span>←</span></button><p className="member-help">برای تغییر پلن یا تمدید، با پذیرش Fit Land Gym تماس بگیر.</p></> }

function ModalShell({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal" onMouseDown={event => event.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button onClick={onClose} aria-label="بستن">×</button></div>{children}</div></div> }
function AddMemberModal({ onClose, onSave }: { onClose: () => void; onSave: (data: { name: string; phone: string; plan: string; locker: string }) => void }) { const [name, setName] = useState(''); const [phone, setPhone] = useState(''); const [plan, setPlan] = useState('سه‌ماهه'); const [locker, setLocker] = useState(''); return <ModalShell title="افزودن عضو جدید" onClose={onClose}><form onSubmit={(event: FormEvent) => { event.preventDefault(); onSave({ name: name || 'عضو جدید', phone: phone || '۰۹۱۲ ۱۲۳ ۴۵۶۷', plan, locker: locker || '—' }) }}><div className="form-grid"><label>نام و نام خانوادگی<input autoFocus required value={name} onChange={e => setName(e.target.value)} placeholder="مثلاً: آرش محمدی"/></label><label>شماره موبایل<input value={phone} onChange={e => setPhone(e.target.value)} placeholder="۰۹۱۲ ۱۲۳ ۴۵۶۷"/></label><label>نوع عضویت<select value={plan} onChange={e => setPlan(e.target.value)}><option>یک‌ماهه</option><option>سه‌ماهه</option><option>شش‌ماهه</option></select></label><label>شماره کمد<input value={locker} onChange={e => setLocker(e.target.value)} placeholder="A-24"/></label></div><div className="modal-actions"><Button variant="ghost" onClick={onClose}>انصراف</Button><Button type="submit">ثبت عضو <span>←</span></Button></div></form></ModalShell> }
function FollowUpModal({ member, onClose, onSent }: { member: Member; onClose: () => void; onSent: () => void }) { const [sent, setSent] = useState(false); return <ModalShell title={`پیگیری ${member.name}`} onClose={onClose}>{sent ? <div className="modal-success"><div>✓</div><h3>پیام ارسال شد</h3><p>پیام پیگیری برای {member.name} ارسال شد و در Timeline ثبت شد.</p><Button onClick={onClose}>بستن</Button></div> : <><div className="followup-member"><Avatar member={member}/><div><strong>{member.name}</strong><span>{member.riskReason}</span></div></div><label>متن پیام<textarea defaultValue={`سلام ${member.name.split(' ')[0]} جان، چند روزه ندیدیمت. منتظرتیم 💪`}/></label><div className="modal-actions"><Button variant="ghost" onClick={onClose}>لغو</Button><Button onClick={() => { setSent(true); onSent() }}>ارسال پیام <span>↗</span></Button></div></>}</ModalShell> }
function PaymentModal({ members, initialMemberId, onClose, onSaved }: { members: Member[]; initialMemberId?: number; onClose: () => void; onSaved: (data: { memberId: number; amount: number; type: string; method: string }) => void }) { const [memberId, setMemberId] = useState(String(initialMemberId || members[0]?.id || 1)); const [amount, setAmount] = useState('2800000'); const [type, setType] = useState('تمدید عضویت'); const [method, setMethod] = useState('درگاه آنلاین'); return <ModalShell title="ثبت پرداخت جدید" onClose={onClose}><form onSubmit={event => { event.preventDefault(); onSaved({ memberId: Number(memberId), amount: Number(toLatinDigits(amount).replace(/[^0-9]/g, '')) || 2800000, type, method }) }}><div className="form-grid"><label>انتخاب عضو<select value={memberId} onChange={e => setMemberId(e.target.value)}>{members.slice(0, 25).map(member => <option value={member.id} key={member.id}>{member.name}</option>)}</select></label><label>مبلغ پرداخت<input value={amount} onChange={e => setAmount(e.target.value)} placeholder="۲۸۰۰۰۰۰"/></label><label>نوع پرداخت<select value={type} onChange={e => setType(e.target.value)}><option>تمدید عضویت</option><option>عضویت جدید</option><option>باقی‌مانده بدهی</option></select></label><label>روش پرداخت<select value={method} onChange={e => setMethod(e.target.value)}><option>درگاه آنلاین</option><option>کارتخوان</option><option>نقدی</option></select></label></div><div className="modal-actions"><Button variant="ghost" onClick={onClose}>انصراف</Button><Button type="submit">ثبت پرداخت <span>←</span></Button></div></form></ModalShell> }
function CheckinModal({ member, onClose, onSaved }: { member: Member; onClose: () => void; onSaved: () => void }) { const [done, setDone] = useState(false); return <ModalShell title="ورود با QR" onClose={onClose}>{done ? <div className="modal-success"><div>✓</div><h3>ورود با موفقیت ثبت شد</h3><p>حضور {member.name} در ساعت ۱۸:۴۲ ثبت شد.</p><Button onClick={onClose}>ادامه</Button></div> : <div className="qr-modal"><p>کد عضو را مقابل دوربین قرار دهید یا به‌صورت نمایشی اسکن کنید.</p><div className="qr-code">{Array.from({ length: 64 }, (_, i) => <i key={i} className={(i * 7) % 11 < 5 ? 'dark' : ''}/>)}</div><span>در انتظار اسکن...</span><Button onClick={() => { setDone(true); onSaved() }} full>شبیه‌سازی اسکن QR</Button></div>}</ModalShell> }
function RenewModal({ member, onClose, onSaved }: { member: Member; onClose: () => void; onSaved: (plan: string) => void }) { const [plan, setPlan] = useState('سه‌ماهه'); return <ModalShell title="تمدید عضویت" onClose={onClose}><div className="renew-summary"><Avatar member={member}/><div><strong>{member.name}</strong><span>عضویت فعلی: {member.plan}</span></div></div><div className="renew-options">{[['سه‌ماهه', '۷,۵۰۰,۰۰۰ تومان'], ['شش‌ماهه', '۱۳,۵۰۰,۰۰۰ تومان']].map(([name, price]) => <button key={name} className={plan === name ? 'selected' : ''} onClick={() => setPlan(name)}><span>{name}</span><strong>{price}</strong>{plan === name && <i>✓</i>}</button>)}</div><p className="modal-note">پس از تایید، تاریخ پایان و وضعیت عضویت به‌روزرسانی می‌شود.</p><div className="modal-actions"><Button variant="ghost" onClick={onClose}>انصراف</Button><Button onClick={() => onSaved(plan)}>تایید تمدید <span>←</span></Button></div></ModalShell> }
function RequestModal({ onClose, onSent }: { onClose: () => void; onSent: (lead: { name: string; phone: string; plan: string }) => void }) { const [sent, setSent] = useState(false); const [name, setName] = useState(''); const [phone, setPhone] = useState(''); const [plan, setPlan] = useState('سه‌ماهه'); return <ModalShell title={sent ? 'درخواست ثبت شد' : 'شروع عضویت در Fit Land Gym'} onClose={onClose}>{sent ? <div className="modal-success"><div>✓</div><h3>درخواست شما ثبت شد</h3><p>کارشناسان باشگاه برای هماهنگی با شما تماس خواهند گرفت.</p><Button onClick={onClose}>خیلی خوب</Button></div> : <form onSubmit={event => { event.preventDefault(); setSent(true); onSent({ name: name || 'درخواست جدید', phone: phone || '۰۹۱۲ ۱۲۳ ۴۵۶۷', plan }) }}><p className="modal-intro">اطلاعاتت را وارد کن تا برای بازدید و شروع عضویت با تو تماس بگیریم.</p><label>نام و نام خانوادگی<input required value={name} onChange={e => setName(e.target.value)} placeholder="مثلاً: نوید صادقی"/></label><label>شماره موبایل<input required value={phone} onChange={e => setPhone(e.target.value)} placeholder="۰۹۱۲ ۱۲۳ ۴۵۶۷"/></label><label>پلن موردنظر<select value={plan} onChange={e => setPlan(e.target.value)}><option>یک‌ماهه</option><option>سه‌ماهه</option><option>شش‌ماهه</option></select></label><label>توضیح اختیاری<textarea placeholder="هدفت از تمرین چیست؟"/></label><div className="modal-actions"><Button variant="ghost" onClick={onClose}>انصراف</Button><Button type="submit">ارسال درخواست <span>←</span></Button></div></form>}</ModalShell> }

export default function App() {
  const [screen, setScreen] = useState<Screen>(() => screenFromPath()); const [members, setMembers] = useState(initialMembers); const [memberships, setMemberships] = useState(initialMemberships); const [payments, setPayments] = useState(initialPayments); const [attendance, setAttendance] = useState(initialAttendance); const [leads, setLeads] = useState(initialLeads); const [timeline, setTimeline] = useState<TimelineItem[]>(() => initialMembers.slice(0, 8).flatMap((member, index) => [{ id: member.id * 10 + 1, memberId: member.id, date: '۲ شهریور', title: 'ثبت پرداخت', detail: 'پرداخت عضویت با موفقیت ثبت شد', tone: 'lime' }, { id: member.id * 10 + 2, memberId: member.id, date: `${4 + index} شهریور`, title: 'ورود به باشگاه', detail: 'از طریق QR', tone: 'blue' }])); const [modal, setModal] = useState<Modal>(() => screenFromPath() === 'request' ? 'request' : null); const [selectedMember, setSelectedMember] = useState<Member | null>(null); const [toasts, setToasts] = useState<Toast[]>([])
  useEffect(() => { const handlePopState = () => { const next = screenFromPath(); setScreen(next); setSelectedMember(null); setModal(next === 'request' ? 'request' : null) }; window.addEventListener('popstate', handlePopState); return () => window.removeEventListener('popstate', handlePopState) }, [])
  const addToast = (message: string, type: Toast['type'] = 'success') => { const id = Date.now(); setToasts(prev => [...prev, { id, message, type }]); window.setTimeout(() => setToasts(prev => prev.filter(item => item.id !== id)), 3200) }
  const go = (next: Screen) => { window.history.pushState({}, '', pathForScreen(next)); setScreen(next); setSelectedMember(null); if (next !== 'request') setModal(null) }
  const openRequest = () => { window.history.pushState({}, '', '/membership'); setScreen('request'); setModal('request') }
  const closeModal = () => { setModal(null); if (screen === 'request') { window.history.pushState({}, '', '/'); setScreen('public') } }
  const openMember = (member: Member) => { setSelectedMember(member); setScreen('members'); window.history.pushState({}, '', '/admin/members') }
  const addTimeline = (memberId: number, title: string, detail: string, tone: TimelineItem['tone'] = 'lime') => setTimeline(prev => [...prev, { id: Date.now(), memberId, date: 'امروز، ۵ شهریور', title, detail, tone }])
  const addMember = ({ name, phone, plan, locker }: { name: string; phone: string; plan: string; locker: string }) => { const newMember: Member = { id: Date.now(), name, phone, status: 'فعال', plan, expiry: '۰۵ آذر ۱۴۰۵', lastVisit: 'هنوز مراجعه نکرده', visits: 0, locker, joined: 'امروز', avatar: initials(name), risk: 'پایدار', riskReason: 'عضو جدید؛ هنوز الگوی حضور شکل نگرفته' }; const price = plan === 'یک‌ماهه' ? 2800000 : plan === 'سه‌ماهه' ? 7500000 : 13500000; setMembers(prev => [newMember, ...prev]); setMemberships(prev => [{ id: newMember.id, memberId: newMember.id, plan, start: 'امروز', end: newMember.expiry, price, status: 'فعال' }, ...prev]); addTimeline(newMember.id, 'عضو جدید ایجاد شد', `پلن ${plan} · آماده شروع`, 'lime'); setModal(null); addToast(`${name} با موفقیت به اعضا اضافه شد`) }
  const convertLead = (lead: Lead) => { const newMember: Member = { id: Date.now(), name: lead.name, phone: lead.phone, status: 'فعال', plan: lead.plan, expiry: '۰۵ آذر ۱۴۰۵', lastVisit: 'هنوز مراجعه نکرده', visits: 0, locker: '—', joined: 'امروز', avatar: initials(lead.name), risk: 'پایدار', riskReason: 'عضو جدید؛ آماده شروع مسیر' }; const price = lead.plan === 'یک‌ماهه' ? 2800000 : lead.plan === 'سه‌ماهه' ? 7500000 : 13500000; setMembers(prev => [newMember, ...prev]); setMemberships(prev => [{ id: newMember.id, memberId: newMember.id, plan: lead.plan, start: 'امروز', end: newMember.expiry, price, status: 'فعال' }, ...prev]); setLeads(prev => prev.map(item => item.id === lead.id ? { ...item, status: 'تبدیل شده' } : item)); addTimeline(newMember.id, 'درخواست به عضو تبدیل شد', `پلن ${lead.plan} · ایجاد از CRM`, 'lime'); addToast(`${lead.name} به عضو باشگاه تبدیل شد`) }
  const recordPayment = ({ memberId, amount, type, method }: { memberId: number; amount: number; type: string; method: string }) => { const member = members.find(item => item.id === memberId); if (!member) return; setPayments(prev => [...prev, { id: Date.now(), memberId, amount, date: 'امروز، ۱۸:۴۰', type, method, status: 'پرداخت موفق' }]); setMembers(prev => prev.map(item => item.id === memberId ? { ...item, status: 'فعال', risk: item.risk === 'در معرض ریزش' ? 'نیازمند توجه' : item.risk } : item)); setMemberships(prev => prev.map(item => item.memberId === memberId ? { ...item, status: 'فعال' } : item)); addTimeline(memberId, 'ثبت پرداخت', `${amount.toLocaleString('fa-IR')} تومان · ${method}`, 'lime'); setModal(null); addToast(`پرداخت ${member.name} با موفقیت ثبت شد`) }
  const recordCheckin = () => { const member = members[0]; if (!member) return; setAttendance(prev => [...prev, { id: Date.now(), memberId: member.id, date: 'امروز، ۵ شهریور', time: '۱۸:۴۲', method: 'QR' }]); setMembers(prev => prev.map(item => item.id === member.id ? { ...item, visits: item.visits + 1, lastVisit: 'امروز، ۱۸:۴۲', risk: item.risk === 'در معرض ریزش' ? 'نیازمند توجه' : item.risk } : item)); addTimeline(member.id, 'ورود به باشگاه', 'از طریق QR · ساعت ۱۸:۴۲', 'blue'); addToast(`حضور ${member.name} ثبت شد`) }
  const followUp = () => { if (!selectedMember) return; addTimeline(selectedMember.id, 'پیام پیگیری ارسال شد', 'پیام دوستانه برای بازگشت عضو', 'orange'); addToast('پیام پیگیری با موفقیت ارسال شد') }
  const followLead = (lead: Lead) => { setLeads(prev => prev.map(item => item.id === lead.id ? { ...item, status: item.status === 'جدید' ? 'در حال پیگیری' : item.status } : item)); addToast(`پیگیری ${lead.name} ثبت شد`) }
  const renewMembership = (plan: string) => { if (!selectedMember) return; const price = plan === 'شش‌ماهه' ? 13500000 : 7500000; const updated = { ...selectedMember, plan, status: 'فعال' as const, expiry: plan === 'شش‌ماهه' ? '۰۵ اسفند ۱۴۰۵' : '۰۵ آذر ۱۴۰۵', risk: 'پایدار' as RiskLevel, riskReason: 'عضویت تمدید شده و وضعیت پایدار است' }; setMembers(prev => prev.map(member => member.id === updated.id ? updated : member)); setMemberships(prev => prev.map(item => item.memberId === updated.id ? { ...item, plan, end: updated.expiry, price, status: 'فعال' } : item)); setSelectedMember(updated); setPayments(prev => [...prev, { id: Date.now(), memberId: updated.id, amount: price, date: 'امروز، ۱۸:۴۰', type: 'تمدید عضویت', method: 'درگاه آنلاین', status: 'پرداخت موفق' }]); addTimeline(updated.id, 'عضویت تمدید شد', `پلن ${plan} · تا ${updated.expiry}`, 'lime'); setModal(null); addToast(`عضویت ${updated.name} با موفقیت تمدید شد`) }
  const handleRequestSent = (lead: { name: string; phone: string; plan: string }) => { setLeads(prev => [{ id: Date.now(), name: lead.name, phone: lead.phone, plan: lead.plan, created: 'همین حالا', status: 'جدید' }, ...prev]); addToast('درخواست عضویت شما ثبت شد') }
  const memberForPortal = members[0]; const modalView = modal === 'add-member' ? <AddMemberModal onClose={closeModal} onSave={addMember}/> : modal === 'follow-up' && selectedMember ? <FollowUpModal member={selectedMember} onClose={closeModal} onSent={followUp}/> : modal === 'payment' ? <PaymentModal members={members} initialMemberId={selectedMember?.id} onClose={closeModal} onSaved={recordPayment}/> : modal === 'attendance' ? <CheckinModal member={memberForPortal} onClose={closeModal} onSaved={recordCheckin}/> : modal === 'renew' && selectedMember ? <RenewModal member={selectedMember} onClose={closeModal} onSaved={renewMembership}/> : modal === 'request' ? <RequestModal onClose={closeModal} onSent={handleRequestSent}/> : null
  const adminContent = useMemo(() => { if (selectedMember && screen === 'members') return <MemberProfile member={members.find(m => m.id === selectedMember.id) || selectedMember} payments={payments} attendance={attendance} timeline={timeline} onBack={() => setSelectedMember(null)} onFollowUp={() => setModal('follow-up')} onPayment={() => setModal('payment')} onRenew={() => setModal('renew')}/>; if (screen === 'admin') return <Dashboard members={members} payments={payments} attendance={attendance} leads={leads} onNavigate={go} onFollowUp={member => { setSelectedMember(member); setModal('follow-up') }} onMember={openMember} onAdd={() => setModal('add-member')} onPayment={() => setModal('payment')} onCheckin={() => setModal('attendance')}/>; if (screen === 'members') return <MembersPage members={members} onMember={openMember} onAdd={() => setModal('add-member')} onToast={addToast}/>; if (screen === 'memberships') return <MembershipsPage members={members} memberships={memberships} onRenew={member => { setSelectedMember(member); setModal('renew') }}/>; if (screen === 'payments') return <PaymentsPage members={members} payments={payments} onPayment={() => setModal('payment')} onToast={addToast}/>; if (screen === 'attendance') return <AttendancePage members={members} attendance={attendance} onCheckin={() => setModal('attendance')}/>; if (screen === 'leads') return <LeadsPage leads={leads} onConvert={convertLead} onFollow={lead => { const member = members.find(m => m.name === lead.name); if (member) { setSelectedMember(member); setModal('follow-up') } else followLead(lead) }} onToast={addToast}/>; return <ReportsPage members={members} payments={payments} leads={leads}/> }, [screen, selectedMember, members, memberships, payments, attendance, leads, timeline])
  if (screen === 'public' || screen === 'request') return <><PublicPage onNavigate={go} onRequest={openRequest}/>{modalView}</>
  if (screen.startsWith('member-')) return <><MemberPortal member={memberForPortal} memberPayments={payments.filter(p => p.memberId === memberForPortal.id)} screen={screen} onNavigate={go} onRenew={() => { setSelectedMember(memberForPortal); setModal('renew') }} onCheckin={() => setModal('attendance')}/>{modalView}</>
  return <><AdminShell screen={screen} onNavigate={go} onPublic={() => go('public')} onMemberPortal={() => go('member-portal')} toasts={toasts}>{adminContent}</AdminShell>{modalView}</>
}
